UPDATE lab_sample
SET status = #{toStatus}, updated_at = #{changedAt}
WHERE id = #{sampleId}
  AND status = #{fromStatus}

UPDATE lab_sample
SET status = #{change.toStatus}, conclusion = #{conclusion},
    completed_at = #{change.changedAt}, updated_at = #{change.changedAt}
WHERE id = #{change.sampleId}
  AND status = #{change.fromStatus}
